---
/**
 * notes.astro — the Notes index: Condensed doctrine + Hubs, with icons.
 * Lists live in src/lib/icons.ts (kept aligned with notes/index.md for agents/Obsidian).
 */
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
import Icon from '../components/Icon.astro';
import { CONDENSED_ENTRIES, HUB_ENTRIES } from '../lib/icons';
import { slugifyFilePath, slugToUrl } from '../lib/slug';

const href = (slug: string) => slugToUrl(slugifyFilePath(slug));
---

<Base title="Notes" description="The best pages to start reading the wiki." active="notes">
  <main class="notes-page">
    <div class="wrap">
      <Constellation mode="full" height="clamp(340px, 56vh, 580px)" />

      <article class="notes-body">
        <p class="notes-lede">
          Use search (⌘K) or the <a href="/map/">Map</a> to browse by connection.
        </p>

        <h2 class="notes-head">Condensed</h2>
        <p class="notes-sub">Each of these sums up one subject in short rules.</p>
        <ul class="entry-list">
          {CONDENSED_ENTRIES.map((e) => (
            <li>
              <a href={href(e.slug)}>
                <Icon name={e.icon} size="17px" class="entry-list__icon" style={`color:${e.color}`} />
                <span class="entry-list__body">
                  <span class="entry-list__title">{e.title}</span><span class="entry-list__blurb">: {e.blurb}</span>
                </span>
              </a>
            </li>
          ))}
        </ul>

        <h2 class="notes-head">Hubs</h2>
        <p class="notes-sub">Each of these is the starting point for one subject.</p>
        <ul class="entry-list">
          {HUB_ENTRIES.map((e) => (
            <li>
              <a href={href(e.slug)}>
                <Icon name={e.icon} size="17px" class="entry-list__icon" style={`color:${e.color}`} />
                <span class="entry-list__body">
                  <span class="entry-list__title">{e.title}</span><span class="entry-list__blurb">: {e.blurb}</span>
                </span>
              </a>
            </li>
          ))}
        </ul>
      </article>
    </div>
  </main>
</Base>

<style>
  .wrap {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 28px 28px 52px;
  }
  .notes-body {
    margin-top: 26px;
  }
  .notes-lede {
    font-family: var(--ming);
    font-size: var(--kb-text-body);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0 0 1.4rem;
  }
  .notes-lede a {
    color: var(--accent);
    text-decoration: none;
    border-bottom: 1px solid color-mix(in oklab, var(--accent) 35%, transparent);
  }
  .notes-lede a:hover {
    border-bottom-color: var(--accent);
  }
  .notes-head {
    font-family: var(--ming);
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--ink);
    margin: 1.6rem 0 0.35rem;
  }
  .notes-sub {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0 0 0.75rem;
    max-width: 64ch;
  }
  .entry-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
  }
  .entry-list a {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    text-decoration: none;
    color: inherit;
  }
  .entry-list a:hover .entry-list__title {
    color: var(--accent);
  }
  .entry-list a :global(.entry-list__icon) {
    flex-shrink: 0;
    margin-top: 2px;
  }
  .entry-list__body {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    min-width: 0;
  }
  .entry-list__title {
    color: var(--ink);
    font-weight: 500;
  }
  .entry-list__blurb {
    color: var(--mut);
  }
  @media (max-width: 640px) {
    .wrap {
      padding: 28px 16px 40px;
    }
  }
</style>

---
/**
 * Chrome.astro — sticky top bar. Ported pixel-for-pixel from the DS KB
 * screens.jsx <Chrome> (sticky header variant) + styles.html .chrome.
 *
 * Brand lockup (mark-nodes-violet + "Knowledge base" + "second brain" kicker),
 * nav with .on active state, theme-toggle button (#theme-toggle, wired by Base),
 * and one inline search field (dropdown results, no modal).
 */
interface Props {
  /** Active nav id — one of "map" | "notes" | "projects" | "journal" | "personal" | "about". */
  active?: string;
}
const { active } = Astro.props;

const nav: { id: string; label: string; href: string }[] = [
  { id: 'map', label: 'Map', href: '/map' },
  { id: 'notes', label: 'Notes', href: '/notes' },
  { id: 'projects', label: 'Projects', href: '/projects' },
  { id: 'journal', label: 'Journal', href: '/journal' },
  { id: 'personal', label: 'Personal', href: '/personal' },
  { id: 'about', label: 'About', href: '/about' },
];
---

<header class="kb-chrome">
  <div class="kb-chrome__inner">
    <a class="kb-brand" href="/">
      <svg class="kb-brand__mark" viewBox="0 0 104 104" width="30" height="30" role="img" aria-label="Logos52" fill="none">
        <g stroke="currentColor" stroke-width="5" stroke-linecap="round">
          <path d="M52 52 L28 52 M52 52 L66 80" />
        </g>
        <g fill="currentColor">
          <circle cx="28" cy="52" r="8" />
          <circle cx="66" cy="80" r="8" />
          <circle cx="80" cy="32" r="7" />
          <circle cx="52" cy="52" r="12" />
        </g>
      </svg>
      <span class="kb-brand__name">Logos52</span>
    </a>
    <nav class="kb-nav">
      {nav.map((n) => (
        <a href={n.href} class:list={['kb-nav__link', { on: active === n.id }]}>
          {n.label}
        </a>
      ))}
    </nav>
    <span class="kb-spacer"></span>
    <button
      type="button"
      id="theme-toggle"
      class="kb-theme-toggle"
      title="Toggle theme"
      aria-label="Toggle theme"
    >
      <span class="kb-theme-toggle__light">☾</span>
      <span class="kb-theme-toggle__dark">☀</span>
    </button>
    <div class="kb-search" data-inline-search>
      <input
        type="search"
        class="kb-search-input"
        data-search-input
        placeholder="Find a note… (⌘K)"
        aria-label="Search notes"
        autocomplete="off"
      />
      <div class="kb-search-results" data-search-results hidden></div>
    </div>
    <button type="button" class="kb-menu-btn" id="kb-menu-btn" aria-label="Open menu" aria-expanded="false">
      ☰
    </button>
  </div>
</header>

<style>
  /* header — sticky, blurred paper, hairline rule (screens.jsx L24) */
  .kb-chrome {
    position: sticky;
    top: 0;
    z-index: 30;
    background: color-mix(in oklab, var(--paper) 88%, transparent);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--rule);
  }
  .kb-chrome__inner {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 0 28px;
    display: flex;
    align-items: center;
    gap: 24px;
    height: 60px;
  }

  /* brand lockup (screens.jsx L26–29) */
  .kb-brand {
    display: flex;
    align-items: center;
    gap: 11px;
    font-weight: 700;
    font-size: 17px;
    color: var(--ink);
    text-decoration: none;
  }
  .kb-brand__mark {
    width: 30px;
    height: 30px;
    flex: none;
    /* node glyph, no seal badge, transparent — a vivid purple brand mark with pop,
     * brightened a touch more on charcoal so it reads. */
    color: #7c3aed;
  }
  :global([data-theme='dark']) .kb-brand__mark {
    color: #a78bfa;
  }
  .kb-brand__name {
    white-space: nowrap;
  }
  .kb-brand__kicker {
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--faint);
    font-weight: 400;
  }

  /* nav (screens.jsx L11–22, L30–32) */
  .kb-nav {
    display: flex;
    gap: 4px;
    margin-left: 8px;
  }
  .kb-nav__link {
    font-family: var(--sans);
    font-size: var(--kb-text-sm);
    color: var(--mut);
    background: transparent;
    border: none;
    padding: 6px 12px;
    border-radius: var(--tsg-radius-sm);
    text-decoration: none;
    cursor: pointer;
  }
  .kb-nav__link.on {
    color: var(--accent);
    background: var(--accent-soft);
  }

  .kb-spacer {
    flex: 1;
  }

  /* theme toggle pill (screens.jsx L34) */
  .kb-theme-toggle {
    font-family: var(--sans);
    font-size: 14px;
    color: var(--mut);
    background: none;
    border: 1px solid var(--rule2);
    border-radius: 999px;
    padding: 5px 12px;
    cursor: pointer;
    margin-right: 10px;
    line-height: 1;
  }
  /* show the glyph matching the *current* theme target (☾ in light, ☀ in dark) */
  .kb-theme-toggle__dark {
    display: none;
  }
  :global(html[data-theme='dark']) .kb-theme-toggle__light {
    display: none;
  }
  :global(html[data-theme='dark']) .kb-theme-toggle__dark {
    display: inline;
  }

  /* inline search — compact input + dropdown (no modal, no blur) */
  .kb-search {
    position: relative;
  }
  .kb-search-input {
    font-family: var(--sans);
    font-size: 12.5px;
    color: var(--ink);
    width: 200px;
    border: 1px solid var(--rule2);
    border-radius: 999px;
    padding: 6px 14px;
    background: var(--card);
    outline: none;
    /* No width transition — animating width reflows the sticky blurred header every frame (choppy ⌘K). */
    transition: border-color var(--dur-fast) var(--ease-standard);
  }
  .kb-search-input::placeholder {
    color: var(--faint);
  }

---
/**
 * map.astro — the Map: the full VAULT GRAPH on top (every note + link), then the six domains listed
 * below as a plain index. The per-domain page lists are computed from the live collection
 * (doctrine-first, knowledge pages only), so they stay current as the vault grows.
 */
import { getCollection } from 'astro:content';
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
import { buildGraph, type NoteInput } from '../lib/graph';
import { deriveTitle } from '../lib/note';
import { slugToUrl } from '../lib/slug';
import { DOMAINS, DOMAIN_LABELS } from '../lib/types';
import { DOMAIN_ICONS } from '../lib/icons';
import Icon from '../components/Icon.astro';

const PER_SECTION = 8;

// One concrete line per domain: a real idea from inside it, useful to the reader — never a
// restatement of the category (the heading and the list already say what it is). Front-facing:
// 02 - System/Writing Standards.md → Specific Beats Generic, Details Not Conclusions (no A-is-A).
const DOMAIN_BLURB: Record<string, string> = {
  learning: 'You remember a page when you recall it later, and when those recalls are spaced out.',
  agentic: 'Agents write the code. The person still sets the direction.',
  language: 'A Chinese character is made of a few hundred parts that get reused.',
  focus: 'You only have so much attention. A feed spends it.',
  mind: 'A decision gets better when you attack your own reasoning before you use it.',
  gen: 'Wealth is owning a share of something that grows without taking more of your hours.',
};

// Doctrine-first ordering: hubs and condensed pages lead, then syntheses, then supporting types,
// with link degree as the tiebreaker. New pages slot in by type, so it stays sensible as it grows.
const TYPE_RANK: Record<string, number> = {
  hub: 100,
  synthesis: 80,
  system: 70,
  model: 60,
  dimension: 60,
  pillar: 45,
  primer: 40,
  workflow: 35,
  technique: 25,
  concept: 20,
  book: 15,
};

const notes = await getCollection('notes');
const input: NoteInput[] = notes.map((n) => ({
  slug: n.id,
  title: deriveTitle(n.data, n.id, n.body),
  type: typeof n.data.type === 'string' ? n.data.type : '',
  body: n.body ?? '',
}));
const full = buildGraph(input);

const degree = new Map<string, number>();
for (const e of full.edges) {
  degree.set(e.source, (degree.get(e.source) ?? 0) + 1);
  degree.set(e.target, (degree.get(e.target) ?? 0) + 1);
}
const score = (n: (typeof full.nodes)[number]) => {
  const tier = Math.max(TYPE_RANK[n.type] ?? 12, /,\s*Condensed$/i.test(n.title) ? 90 : 0);
  return tier * 1000 + (degree.get(n.slug) ?? 0);
};

const byDomain = new Map<string, (typeof full.nodes)[number][]>();
for (const n of full.nodes) {
  if (!n.slug.startsWith('wiki/')) continue; // knowledge pages only — exclude journal, index, about
  (byDomain.get(n.domain) ?? byDomain.set(n.domain, []).get(n.domain)!).push(n);
}

const sections = DOMAINS.map((d) => {
  const all = (byDomain.get(d) ?? []).sort((a, b) => score(b) - score(a) || a.title.localeCompare(b.title));
  return {
    domain: d,
    label: DOMAIN_LABELS[d],
    icon: DOMAIN_ICONS[d],
    items: all.slice(0, PER_SECTION),
  };
});
---

<Base title="Map" description="The vault graph, and the knowledge base by domain." active="map">
  <main class="map-page">
    <div class="wrap">
      <header class="map-head">
        <h1 class="map-head__title">The vault</h1>
      </header>

      <Constellation mode="full" domainLabels height="clamp(460px, 66vh, 780px)" />
    </div>

    <article class="prose">
      <h2 class="prose__head">The six domains</h2>
      {sections.map((s) => (
        <section class="domain">
          <h3>
            <a href={`/domains/${s.domain}/`}>
              <Icon name={s.icon} size="1.05em" class="domain__icon" style={`color:var(--d-${s.domain})`} />
              {s.label}
            </a>
          </h3>
          <p class="domain__blurb">{DOMAIN_BLURB[s.domain]}</p>
          <ul>
            {s.items.map((it) => (
              <li>
                <a href={slugToUrl(it.slug)}>{it.title}</a>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </article>
  </main>
</Base>

<style>
  .wrap {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 28px 28px 0;
  }
  .map-head {
    max-width: 60ch;
    margin: 8px 0 16px;
  }
  .map-head__title {
    font-family: var(--ming);
    font-weight: 500;
    font-size: var(--kb-text-h1-shell);
    line-height: 1.2;
    margin: 0 0 0.4rem;
    color: var(--ink);
  }
  .map-head__lede {
    font-family: var(--mono);
    font-size: var(--kb-text-xs);
    letter-spacing: 0.04em;
    line-height: var(--kb-lh-snug);
    color: var(--mut);
    margin: 0;
  }

  /* six domains — plain index below the graph */
  .prose {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 30px 28px 60px;
  }
  .prose__head {
    font-family: var(--ming);
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--ink);
    margin: 0 0 0.2rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--rule);
  }
  .domain h3 {
    font-family: var(--ming);
    font-size: 1.02rem;
    font-weight: 600;
    margin: 1.5rem 0 0.35rem;
    color: var(--ink);
  }
  .domain h3 a {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: inherit;
    text-decoration: none;
  }
  .domain h3 a:hover {
    text-decoration: underline;
  }
  .domain h3 a :global(.domain__icon) {
    flex-shrink: 0;
  }
  .domain__blurb {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0.15rem 0 0.5rem;
    max-width: 64ch;
  }
  .domain ul {
    list-style: disc;
    padding-left: 1.25rem;
    margin: 0.2rem 0 0;
    columns: 2;
    column-gap: 44px;
  }
  .domain li {
    font-size: var(--kb-text-base);
    line-height: var(--kb-lh-body);
    color: var(--mut);
    margin: 0.12rem 0;
    break-inside: avoid;
  }
  .domain li a {
    color: var(--ink);
    text-decoration: none;
  }
  .domain li a:hover {
    color: var(--accent);
    text-decoration: underline;
  }
  @media (max-width: 640px) {
    .wrap {
      padding: 28px 16px 0;
    }
    .prose {
      padding: 24px 16px 40px;
    }
    .domain ul {
      columns: 1;
    }
  }
</style>

---
/**
 * folder/[...folder].astro — one listing per vault folder.
 * Breadcrumbs on a note link here, so "Systems" lists the Systems folder
 * instead of the whole domain.
 */
import { getCollection } from 'astro:content';
import type { GetStaticPaths } from 'astro';
import Base from '../../layouts/Base.astro';
import { deriveTitle, deriveSummary } from '../../lib/note';
import { slugToUrl } from '../../lib/slug';

function display(seg: string): string {
  return seg.replace(/--and--/g, ' & ').replace(/-+/g, ' ');
}

function clip(s: string): string {
  const t = s.replace(/\s+/g, ' ').trim();
  if (t.length <= 160) return t;
  const cut = t.slice(0, 160);
  const sp = cut.lastIndexOf(' ');
  return sp > 80 ? cut.slice(0, sp) : cut;
}

export const getStaticPaths = (async () => {
  const notes = await getCollection('notes');
  const folders = new Set<string>();
  for (const n of notes) {
    const parts = n.id.split('/').filter(Boolean);
    for (let i = 1; i < parts.length; i++) folders.add(parts.slice(0, i).join('/'));
  }
  return [...folders].sort().map((folder) => ({ params: { folder } }));
}) satisfies GetStaticPaths;

const { folder } = Astro.params as { folder: string };
const notes = await getCollection('notes');

type Page = { title: string; href: string; summary: string };
type Group = { name: string; href: string; count: number };

const pages: Page[] = [];
const groups = new Map<string, number>();
let section: Page | null = null;

for (const n of notes) {
  if (n.id === folder) {
    section = {
      title: deriveTitle(n.data, n.id, n.body),
      href: slugToUrl(n.id),
      summary: clip(deriveSummary(n.data, n.body)),
    };
    continue;
  }
  if (!n.id.startsWith(folder + '/')) continue;
  const rest = n.id.slice(folder.length + 1);
  const slash = rest.indexOf('/');
  if (slash === -1) {
    pages.push({
      title: deriveTitle(n.data, n.id, n.body),
      href: slugToUrl(n.id),
      summary: clip(deriveSummary(n.data, n.body)),
    });
  } else {
    const seg = rest.slice(0, slash);
    groups.set(seg, (groups.get(seg) ?? 0) + 1);
  }
}

pages.sort((a, b) => a.title.localeCompare(b.title));
const subfolders: Group[] = [...groups.entries()]
  .map(([name, count]) => ({
    name: display(name),
    href: `/folder/${folder}/${name}/`,
    count,
  }))
  .sort((a, b) => a.name.localeCompare(b.name));

const parts = folder.split('/');
const title = display(parts[parts.length - 1] ?? folder);
const parent = parts.length > 1 ? `/folder/${parts.slice(0, -1).join('/')}/` : '';

---
/**
 * Backlinks.astro — "Backlinks · N" sticky-aside panel.
 * Mirrors the NotePage aside backlinks block in the DS screens.jsx: mono uppercase
 * heading with the count, each entry a title link (var(--ink)) with a hairline
 * bottom rule and a faint context line below it.
 */
import type { Backlink } from '../lib/types';

interface Props {
  items: Backlink[];
}
const { items } = Astro.props;
const slugToHref = (slug: string) => '/' + slug.replace(/^\/+/, '').replace(/\/+$/, '') + '/';
const SHOWN = 5;
const head = items.slice(0, SHOWN);
const rest = items.slice(SHOWN);
---

{
  items.length > 0 && (
    <section class="kb-backlinks" aria-label="Backlinks">
      <h3 class="kb-side-h">Backlinks · {items.length}</h3>
      <div class="kb-backlinks-list">
        {head.map((b) => (
          <a href={slugToHref(b.slug)} class="kb-backlink">
            {b.title}
            {b.context && <span class="kb-backlink-ctx">{b.context}</span>}
          </a>
        ))}
      </div>
      {rest.length > 0 && (
        <details class="kb-backlinks-more">
          <summary>{rest.length} more</summary>
          <div class="kb-backlinks-list">
            {rest.map((b) => (
              <a href={slugToHref(b.slug)} class="kb-backlink">
                {b.title}
                {b.context && <span class="kb-backlink-ctx">{b.context}</span>}
              </a>
            ))}
          </div>
        </details>
      )}
    </section>
  )
}

<style>
  .kb-side-h {
    font-family: var(--mono);
    font-size: 0.75rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--mut);
    margin: 0 0 10px;
    font-weight: 600;
  }
  .kb-backlinks-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .kb-backlink {
    font-size: 13px;
    color: var(--ink);
    text-decoration: none;
    border-bottom: 1px solid var(--rule);
