+  record('understand h1', 'The AI Industrial Revolution', note.h1, note.h1 === 'The AI Industrial Revolution');
+  record('understand dek', 'absent', String(note.dek), note.dek === false);
+  record('understand type', 'Concept', note.type, note.type === 'Concept');
+  record('understand crumb', 'wiki → /folder/wiki/', `${note.crumbText} ${note.crumb}`, note.crumbText.toLowerCase() === 'wiki' && note.crumb === '/folder/wiki/');
+  record('understand related fold', 'N more related pages', note.related, /^\d+ more related pages$/.test(note.related));
