+  record('prose link found', 'Agentic Engineering, Condensed', clicked.ok ? clicked.text : 'missing', clicked.ok);
+  await page.waitForFunction(() => /Agentic-Engineering,-Condensed/.test(location.pathname), { timeout: 20000 });
+  await page.waitForSelector('h1.kb-note-title');
+  await page.screenshot({ path: `${EVIDENCE}/note-after-prose-link.png` });
+  const next = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.kb-note-title')?.textContent.trim() ?? '',
+  }));
+  record('prose land h1', 'Agentic Engineering, Condensed', `${next.h1} @ ${next.url}`, next.h1 === 'Agentic Engineering, Condensed');
+
+  await page.evaluate(() => {
+    const notes = [...document.querySelectorAll('a.kb-nav__link')].find((a) => a.textContent.trim() === 'Notes');
+    notes?.click();
+  });
