+  record('notes omits extra hubs', 'no Using Grok Bot / pstack / Cursor Cloud Agents / Picking a computer', notes.titles.filter((t) => /Grok Bot|pstack|Cursor Cloud Agents|Picking a computer/.test(t)).join(', ') || 'none of those four', !notes.titles.some((t) => /Grok Bot|pstack|Cursor Cloud Agents|Picking a computer/.test(t)));
+
+  await page.evaluate(() => {
+    const title = [...document.querySelectorAll('.entry-list__title')].find((el) => el.textContent.trim() === 'Learning, Condensed');
+    title?.closest('a')?.click();
+  });
+  await page.waitForSelector('h1.kb-note-title');
+  await page.waitForFunction(() => /Learning,-Condensed/.test(location.pathname), { timeout: 20000 });
+  await page.screenshot({ path: `${EVIDENCE}/note-learning-condensed.png` });
+  const condensed = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.kb-note-title')?.textContent.trim() ?? '',
+    dek: document.querySelector('p.kb-note-dek')?.textContent.trim() ?? '',
+    type: document.querySelector('.kb-type-tag')?.textContent.trim() ?? '',
+    crumb: document.querySelector('.kb-crumb a')?.getAttribute('href') ?? '',
+  }));
+  record('condensed h1', 'Learning, Condensed', condensed.h1, condensed.h1 === 'Learning, Condensed');
+  record('condensed dek', 'starts The whole learning corpus', condensed.dek.slice(0, 80), condensed.dek.startsWith('The whole learning corpus'));
+  record('condensed type', 'Condensed', condensed.type, condensed.type === 'Condensed');
+  record('condensed crumb', '/folder/wiki/', condensed.crumb, condensed.crumb === '/folder/wiki/');
+
+  await page.evaluate(() => {
+    const notes = [...document.querySelectorAll('a.kb-nav__link')].find((a) => a.textContent.trim() === 'Notes');
+    notes?.click();
+  });
+  await page.waitForFunction(() => /\/notes\/?$/.test(location.pathname), { timeout: 20000 });
+  await page.waitForSelector('input[aria-label="Search notes"]');
+  await page.click('input[aria-label="Search notes"]');
+  await page.type('input[aria-label="Search notes"]', 'Vibe Coding', { delay: 30 });
+  await page.waitForFunction(() => {
+    const box = document.querySelector('[data-search-results]');
+    if (!box || box.hasAttribute('hidden')) return false;
+    const text = box.textContent || '';
+    if (text.includes('Search index loading')) return false;
+    return !!box.querySelector('a.kb-ac-row, .kb-ac-empty');
+  }, { timeout: 30000 });
+  await page.screenshot({ path: `${EVIDENCE}/search-results.png` });
+  const search = await page.evaluate(() => {
+    const box = document.querySelector('[data-search-results]');
+    const row = box?.querySelector('a.kb-ac-row');
+    return {
+      hidden: box?.hasAttribute('hidden') ?? true,
+      title: row?.querySelector('.kb-ac-title')?.textContent.trim() ?? '',
+      empty: box?.querySelector('.kb-ac-empty')?.textContent.trim() ?? '',
+      count: box?.querySelectorAll('a.kb-ac-row').length ?? 0,
+    };
+  });
+  record('search open', 'rows for Vibe Coding', search.empty || `${search.count} first=${search.title}`, !search.hidden && search.count > 0 && /vibe coding/i.test(search.title));
+
+  await page.click('[data-search-results] a.kb-ac-row');
+  await page.waitForSelector('article[data-pagefind-body] h1.kb-note-title');
+  await page.screenshot({ path: `${EVIDENCE}/search-landed.png` });
+  const landed = await page.evaluate(() => ({
+    url: location.pathname,
+    h1: document.querySelector('h1.kb-note-title')?.textContent.trim() ?? '',
+  }));
+  record('search land', search.title, `${landed.h1} @ ${landed.url}`, landed.h1 === search.title);
+} catch (err) {
+  record('drive exception', 'none', String(err && err.stack ? err.stack : err), false);
+  try {
+    await page.screenshot({ path: `${EVIDENCE}/drive-error.png` });
+  } catch {}
+} finally {
+  const fails = rows.filter((r) => r.pass === 'fail').length;
+  const md = [
+    '# Drive report',
+    '',
+    `Base: ${BASE}`,
+    `Fails: ${fails} / ${rows.length}`,
+    '',
+    '| Step | Expected | Observed | Result |',
+    '|---|---|---|---|',
+    ...rows.map((r) => `| ${r.step} | ${r.expected.replaceAll('|', '/')} | ${r.observed.replaceAll('|', '/').replaceAll('\n', ' ')} | ${r.pass} |`),
+    '',
+  ].join('\n');
+  writeFileSync(`${EVIDENCE}/drive-report.md`, md);
+  console.log(`WROTE ${EVIDENCE}/drive-report.md fails=${fails}`);
+  await page.close();
+  browser.disconnect();
+  process.exit(fails ? 1 : 0);
+}

