    try:
        lines=open(path).read().splitlines()[1:]
    except FileNotFoundError:
        continue
    for line in lines:
        parts=line.split()
        local=parts[1]
        ip,port=local.split(':')
        if int(port,16)==9222:
            print(path, local, 'state', parts[3])
